/* HEXFIELD / RULE STUDIO 302. Offline-capable, deterministic mark laws.
 * A model image, a user photograph, an archive field or a synthetic scene
 * is only a reference. The final pixels are generated by the rule engine.
 */
import {SUBJECTS,LAWS,MARKS,REWORKS,makeRecipe,mutateRecipe,drawReality,applyRules,
  noteRuleVerdict,noteLineage,describeRecipe,buildRulePrompt,RULE_STORE} from './rule-engine.js';
import {createAbstractionLoop} from './abstraction-loop.js';
import {deriveBetweenFrames} from './frame-derivation.js';
import {paintHeldMotifs,advanceMotifMemory,motifEvidence} from './motif-memory.js';
import {extractStructuralIdea,paintInheritedIdeas,advanceStructuralIdeas,
 heritageEvidence,judgeStructuralIdeas} from './structural-heritage.js';
import {createCreativePerformance} from './creative-performance.js';
import {measureGoldenTaste,explainGolden,diagnoseGolden,
  compareGoldenTaste} from './golden-taste.js';
import {publishSource} from './source-mixer.js';
import {evolveSeed,rankNoveltyCandidates,assessCanvas,commitCanvas,
  methodSignature,snapshotNoveltyMemory} from './nonredundancy.js';
const $=id=>document.getElementById(id);
const GALLERY='hexfield.rule-studio.gallery.v1';
const CURRENT='hexfield.rule-studio.current.v1';
function read(key){try{return JSON.parse(localStorage.getItem(key)||'null')}catch{return null}}
function store(key,data){try{localStorage.setItem(key,JSON.stringify(data));return true}catch{return false}}
const options=(catalog,empty)=>'<option value="surprise">'+empty+'</option>'+
  Object.entries(catalog).map(([value,label])=>'<option value="'+value+'">'+label+'</option>').join('');
function optionMarkup(){
 $('ruleSubject').innerHTML=options(SUBJECTS,'Surprise subject');
 $('rulePrimary').innerHTML=options(LAWS,'Surprise law');
 $('ruleSecondary').innerHTML='<option value="none">No second law</option>'+
   Object.entries(LAWS).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('');
 $('ruleMark').innerHTML=options(MARKS,'Surprise mark system');
 $('ruleRework').innerHTML=Object.entries(REWORKS).map(([k,v])=>
   '<option value="'+k+'">'+v+'</option>').join('');
}
const safe=(text,n=220)=>String(text||'').slice(0,n);
const text=(id,message)=>{$(id).textContent=message;};
function fileToImage(file){
 return new Promise((resolve,reject)=>{
   if(!file||!file.type.startsWith('image/')||file.size>8e6)return reject(Error('Choose an image under 8 MB.'));
   const url=URL.createObjectURL(file);const img=new Image();
   img.onload=()=>{URL.revokeObjectURL(url);resolve(img);};
   img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Could not decode the picture.'));};
   img.src=url;
 });
}
function canvasOf(w=960,h=600){const c=document.createElement('canvas');c.width=w;c.height=h;return c;}
function fromImage(img,w=960,h=600){
 const c=canvasOf(w,h),g=c.getContext('2d');
 g.fillStyle='#ded9ca';g.fillRect(0,0,w,h);
 const ratio=Math.min(w/(img.naturalWidth||img.width),h/(img.naturalHeight||img.height));
 const dw=(img.naturalWidth||img.width)*ratio,dh=(img.naturalHeight||img.height)*ratio;
 g.drawImage(img,(w-dw)/2,(h-dh)/2,dw,dh);return c;
}
function thumbnail(canvas){const out=canvasOf(248,156);out.getContext('2d').drawImage(canvas,0,0,248,156);return out.toDataURL('image/webp',.68);}
function persistCanvas(canvas,recipe,judged){
 const small=canvasOf(720,450);small.getContext('2d').drawImage(canvas,0,0,720,450);
 store(CURRENT,{image:small.toDataURL('image/webp',.73),recipe,judged});
}
export function initRuleStudio(){
 optionMarkup();
 let current=null,upload=null,parentCanvas=null,realitySource=null,
   sequence=0,manualMotifs=[],manualIdeas=[],lastOrigin='manual';
 const context=$('ruleArtwork').getContext('2d');
 const status=m=>text('ruleStatus',m);
 const theatre=createCreativePerformance({
   host:document.querySelector('.rule-frame'),
   canvas:$('ruleArtwork'),name:'rules'
 });
 let lastPhi=null;
 function displayPhi(canvas){
   const s=measureGoldenTaste(canvas,{mode:'rule-studio'});
   const verdict=diagnoseGolden(s);
   const delta=compareGoldenTaste(lastPhi,s);
   const el=$('ruleGoldenEvidence');
   if(el){
     el.textContent='φ×φ / '+explainGolden(s)+
       (delta&&!delta.first?' / '+delta.description:'')+
       ' / NEXT: '+verdict.instruction;
     el.dataset.qualifies=String(s.qualifies);
   }
   lastPhi=s;
   return s;
 }
 function showLoopHistory(rows){
   const root=$('ruleLoopHistory');root.replaceChildren();
   for(const item of rows.slice(-10).reverse()){
     const el=document.createElement('figure');el.className='rule-loop-frame';
     const img=document.createElement('img');img.src=item.thumb;
     img.alt='Abstract generation '+item.cycle;
     const caption=document.createElement('figcaption');
     caption.textContent='#'+item.cycle+' / '+item.blend+' / '+item.law+
      ' / '+item.mark+' / '+(item.derivedBy||'fresh')+
       ' · '+Math.round((item.retained||0)*100)+'% frame retained · '+
       (item.survivors||0)+' pixels held'+
      ' · '+(item.inheritedIdeas||0)+' shape genes';
     el.append(img,caption);root.append(el);
   }
 }
 function showHeritage(ideas=[]){
   const root=$('ruleGenealogy');
   if(!root)return;
   root.replaceChildren();
   for(const gene of ideas.slice(0,2)){
     const panel=document.createElement('figure');
     panel.className='heritage-specimen';
     const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');
     svg.setAttribute('viewBox','0 0 100 75');
     svg.setAttribute('aria-label','Actual sampled inherited contour '+gene.id);
     svg.setAttribute('role','img');
     const path=document.createElementNS('http://www.w3.org/2000/svg','path');
     const d=(gene.outline||[]).map((point,i)=>
       (i?'L':'M')+(4+point[0]*92).toFixed(1)+' '+
       (4+point[1]*66).toFixed(1)).join(' ')+' Z';
     path.setAttribute('d',d);
     path.setAttribute('fill','none');
     path.setAttribute('stroke','#c2dca2');
     path.setAttribute('stroke-width','2.5');
     path.setAttribute('stroke-linejoin','round');
     svg.append(path);panel.append(svg);
     const info=document.createElement('figcaption');
     info.textContent=(gene.recalled?'RETURNED '+gene.recalled+'× / ':'HERITAGE / ')+
       'generation '+gene.generation+
       ' / '+gene.name+' / '+gene.material+
       ' / AGE '+gene.age+'/'+gene.ttl+
       ' / preference '+gene.trust.toFixed(2);
     panel.append(info);root.append(panel);
   }
 }
 function loopOptions(){
   return {speed:Number($('ruleLoopSpeed').value)||3000,
     mixMode:$('ruleMixMode').value,
     lockLaw:$('ruleLockLaw').checked,
     subject:$('ruleSubject').value,
     law:$('rulePrimary').value,
     secondary:$('ruleSecondary').value,
     mark:$('ruleMark').value};
 }
 const loop=createAbstractionLoop({
   width:960,height:600,
   getParent:()=>current?.canvas||null,
   getUploaded:()=>upload,
   onFrame(result){
     const {canvas,recipe,cycle,metrics,blend,sources,novelty,nonredundancy,
       survival,heritage,trials,derivation}=result;
     const before=current?.canvas||null;
     lastOrigin='loop';
     context.clearRect(0,0,960,600);context.drawImage(canvas,0,0,960,600);
     current={recipe,canvas,judged:false,metrics};
     parentCanvas=canvas;
     displayPhi(canvas);
     const duration=Math.min(2450,Math.max(1050,
       (Number($('ruleLoopSpeed').value)||3000)-260));
     void theatre.play({kind:'rule',recipe,trace:metrics.trace,
       survival,heritage,trials,parent:before,final:canvas,duration});
     $('ruleArtwork').hidden=false;$('ruleEmpty').hidden=true;
     $('ruleKeep').disabled=false;$('ruleReject').disabled=false;
     $('ruleReworkBtn').disabled=false;$('ruleSave').disabled=false;
     text('ruleCaption',describeRecipe(recipe));
     text('ruleEvidence','GENERATION '+cycle+' / '+metrics.strokes+
       ' marks / '+metrics.skipped+' removed / '+blend.toUpperCase()+
       ' / '+sources.join(' + ')+
       (derivation?' / DERIVATION '+derivation.method.toUpperCase()+
         ' / '+Math.round(derivation.retained*100)+'% retained frame':'')+
       ' / visual change '+(novelty*100).toFixed(1)+
       '% / '+(survival?.carried||0)+' original-pixel islands / '+
       (heritage?.drawn?.length||0)+' reconstructed shape identities'+
       (heritage?.drawn?.length?' / '+heritage.drawn.map(x=>
         x.was+' → '+x.material).join(', '):''));
     status('Reabstracting generation '+cycle+
       '. Shared novelty '+((nonredundancy?.novelty||0)*100).toFixed(1)+
       '%, structural complexity '+((nonredundancy?.complexity||0)*100).toFixed(1)+
       '%. '+(survival?.carried||0)+' motifs survived this pass; '+
       (survival?.available||0)+' physical references, '+
       (heritage?.living?.length||0)+' reconstructable geometry genes / '+
       'W '+Math.round((heritage?.tradeoff?.W||0)*100)+
       ' φ '+Math.round((heritage?.tradeoff?.phi||0)*100)+
       ' H '+Math.round((heritage?.tradeoff?.H||0)*100)+'.');
     if(cycle%4===0){persistCanvas(canvas,recipe,false);publishSource(canvas,'rules',recipe);}
   },
   onState(info){
     $('ruleLoopStart').disabled=info.running;
     $('ruleLoopStop').disabled=!info.running;
     $('ruleLoopOnce').disabled=info.running;
     const visible=info.motifs||[],genomes=info.ideas||[];
     showHeritage(genomes);
     const survivorStatus=$('ruleSurvivors');
     if(survivorStatus){
       survivorStatus.textContent='SURVIVING IDEAS / '+visible.length+
         ' ancestral pixel islands · '+genomes.length+
         ' independently reconstructable shape genes'+
         (genomes.length?' / '+genomes.map(g=>
           (g.recalled?'RETURNED IDEA '+g.recalled+'× ':'')+
           g.name+' #'+g.generation+' '+g.material).join(' · '):'')+
         ' · KEEP or REJECT teaches which lineage to retain.';
     }
     const sources=info.sourceNames?.length?info.sourceNames.join(' + '):'not rendered yet';
     text('ruleLoopStatus',(info.running?'LIVE':'PAUSED')+' / '+info.cycle+
       ' passes / blending: '+(info.method||'evolving')+' / renderers: '+sources+
       (info.waiting?' / suspended while page is hidden':'')+
       (info.nonredundancy?' / GLOBAL W novelty '+
         (info.nonredundancy.novelty*100).toFixed(1)+
         '% · complexity '+(info.nonredundancy.complexity*100).toFixed(1)+'%':'')+
       (info.lastError?' / '+info.lastError:''));
     showLoopHistory(info.history||[]);
   },
   onError(error){status('Abstraction recovered from a renderer error: '+safe(error?.message||error));}
 });
 function present(recipe,source,revision=false){
   if(!source)throw Error('No input picture to constrain');
   const before=current?.canvas||null,target=canvasOf();
   const metrics=applyRules(source,target,recipe,{
     iteration:recipe.generation,trace:true
   });
   if(revision&&before){
     const derived=deriveBetweenFrames(before,target,{
       seed:recipe.seed,cycle:recipe.generation,
       method:current?.recipe?.application
     });
     recipe.application=derived.method;
     const ink=target.getContext('2d');
     ink.save();ink.setTransform(1,0,0,1,0,0);
     ink.drawImage(derived.canvas,0,0,target.width,target.height);ink.restore();
     metrics.derivation=derived.method;
     metrics.retained=derived.retained;
   }
   if(!revision){manualMotifs=[];manualIdeas=[];} // New chapter.
   if(revision&&before&&!manualIdeas.length){
     const recovered=extractStructuralIdea(before,{
       seed:current?.recipe?.seed||recipe.seed,cycle:Math.max(0,recipe.generation-1)
     });
     if(recovered)manualIdeas=[recovered];
   }
   if(revision&&before&&!manualMotifs.length)
     manualMotifs=advanceMotifMemory([],before,{
       seed:before?.recipe?.seed||recipe.seed,cycle:1,parent:before
     });
   const held=revision?paintHeldMotifs(target,manualMotifs,{
     cycle:recipe.generation,opacity:.96
   }):{held:[],coverage:0};
   const inherited=motifEvidence(manualMotifs);
   // Reconstruct the same contour using the new law's geometry and
   // pigment method. The previous raster island remains independent.
   const hereditary=revision?paintInheritedIdeas(target,manualIdeas,{
     seed:recipe.seed,cycle:recipe.generation,recipe
   }):{drawn:[],score:0,coverage:0};
   if(revision){
     manualMotifs=advanceMotifMemory(manualMotifs,target,{
       seed:recipe.seed,cycle:recipe.generation+1,parent:before
     });
     manualIdeas=advanceStructuralIdeas(manualIdeas,target,{
       seed:recipe.seed,cycle:recipe.generation+1,
       source:before,rendered:hereditary
     });
   }
   lastOrigin='manual';
   const method=methodSignature({
     mode:'rule-studio',subject:recipe.subject,primary:recipe.primary,
     secondary:recipe.secondary,mark:recipe.mark,rework:recipe.rework
   });
   const analysis=assessCanvas(target,{
     mode:'rule-studio',method,parent:before
   });
   const W=commitCanvas(target,{
     mode:'rule-studio',method,seed:recipe.seed,parentId:recipe.parentId,evaluation:analysis
   });
   context.clearRect(0,0,960,600);context.drawImage(target,0,0);
   current={recipe,canvas:target,judged:false,metrics,nonredundancy:W};parentCanvas=target;
   displayPhi(target);
   showHeritage(heritageEvidence(manualIdeas));
   void theatre.play({kind:'rule',recipe,trace:metrics.trace,
     survival:{held:held.held,available:manualMotifs.length},
     heritage:{...hereditary,tradeoff:null},
     parent:before,final:target,duration:2100});
   $('ruleEmpty').hidden=true;
   $('ruleArtwork').hidden=false;
   $('ruleKeep').disabled=false;$('ruleReject').disabled=false;$('ruleReworkBtn').disabled=false;
   $('ruleSave').disabled=false;
   text('ruleCaption',describeRecipe(recipe));
   text('ruleEvidence',metrics.strokes+' actual marks · '+metrics.skipped+
     ' omitted · '+(recipe.parentId?' CHILD OF '+recipe.parentId.slice(0,7):'ORIGINAL')+
     (revision?' · PAINTED FROM PREVIOUS IMAGE · '+held.held.length+
       ' physical old forms survived · '+hereditary.drawn.length+
       ' structural ideas reconstructed':''));
   status('W / global non-redundancy: '+(W.novelty*100).toFixed(1)+
     '% new against this studio, '+(W.globalNovelty*100).toFixed(1)+
     '% new globally, complexity '+(W.complexity*100).toFixed(1)+'%.'+
     (W.redundant?' Repeated image: try a new law.':''));
   noteLineage(recipe);persistCanvas(target,recipe,false);
   publishSource(target,'rules',recipe);
   return current;
 }
 async function sourceFor(recipe){
   const origin=$('ruleReference').value;
   if(origin==='file'){
     if(!upload)throw Error('Select a reference image first.');
     return fromImage(upload);
   }
   if(origin==='imagined'){
     const img=$('imaginePicture');
     if(img&&img.complete&&img.naturalWidth)return fromImage(img);
     throw Error('Generate a picture in IMAGINE first or select a different reference source.');
   }
   if(origin==='last'&&current)return current.canvas;
   const reality=canvasOf();drawReality(reality,recipe.subject,recipe.seed);return reality;
 }
 function selections(){
   return {subject:$('ruleSubject').value,primary:$('rulePrimary').value,
     secondary:$('ruleSecondary').value,mark:$('ruleMark').value,rework:$('ruleRework').value};
 }
 async function paintFresh(){
   try{
     const values=selections(),sourceSeed=current?.recipe?.seed??Math.floor(Math.random()*4294967295);
     const options=[];
     for(let i=0;i<3;i++){
       const derived=evolveSeed(sourceSeed,(current?.recipe?.generation||0)+1,i,'rule-paint');
       const recipe=makeRecipe({...values,seed:derived,
         parentId:current?.recipe?.id||null,
         generation:(current?.recipe?.generation||0)+1});
       const source=await sourceFor(recipe),candidate=canvasOf();
       applyRules(source,candidate,recipe,{iteration:recipe.generation});
       const method=methodSignature({
         mode:'rule-studio',subject:recipe.subject,primary:recipe.primary,
         secondary:recipe.secondary,mark:recipe.mark,rework:recipe.rework
       });
       options.push({recipe,source,canvas:candidate,method});
     }
     const [chosen]=rankNoveltyCandidates(options,{
       mode:'rule-studio',parent:current?.canvas||null
     });
     realitySource=chosen.source;
     present(chosen.recipe,chosen.source);
   }catch(error){status(safe(error.message));}
 }
 function child(focus){
   if(!current){void paintFresh();return;}
   const ancestor=current.recipe;
   const r=mutateRecipe(ancestor,focus);
   // Controlled changes: either keep the same subject or keep the same laws.
   if(focus==='subject'){r.primary=ancestor.primary;r.secondary=ancestor.secondary;r.mark=ancestor.mark;}
   if(focus==='law'){r.subject=ancestor.subject;r.mark=ancestor.mark;}
   if(focus==='mark'){r.subject=ancestor.subject;r.primary=ancestor.primary;r.secondary=ancestor.secondary;}
   // Controlled comparisons must change ACTUAL picture content.
   // Law/mark trials reuse the same raw reality anchor; subject trials make
   // a NEW source depicting the new subject instead of relabelling pixels.
   let base=realitySource||parentCanvas||current.canvas;
   if(focus==='subject'){
     base=canvasOf();drawReality(base,r.subject,ancestor.seed);
     realitySource=base;
   }
   r.rework='none';
   present(r,base,true);
   $('ruleSubject').value=r.subject;$('rulePrimary').value=r.primary;$('ruleMark').value=r.mark;
 }
 function rework(){
   if(!current){status('Paint a parent picture before reworking.');return;}
   const ancestor=current.recipe;
   const opts=selections();
   const next=makeRecipe({...opts,parentId:ancestor.id,
     generation:ancestor.generation+1,
     seed:evolveSeed(ancestor.seed,ancestor.generation+1,0,'rule-rework')});
   if(next.rework==='none')next.rework='abstract_masses';
   const prior=current.canvas;
   realitySource=prior;
   present(next,prior,true);
 }
 function gallery(){
   const rows=read(GALLERY)||[],root=$('ruleGallery');
   root.replaceChildren();
   for(const entry of rows.slice(-12).reverse()){
     const el=document.createElement('figure');el.className='rule-card';
     const img=document.createElement('img');img.src=entry.thumb;img.alt='Saved constrained study';
     const title=document.createElement('figcaption');
     title.textContent=(entry.recipe.parentId?'CHILD':'ROOT')+' / '+entry.recipe.primary+' / '+entry.recipe.mark;
     el.append(img,title);root.append(el);
   }
 }
 function vote(liked){
   loop.pause();
   if(!current||current.judged)return;
   const critique=safe($('ruleCritique').value,230);
   noteRuleVerdict(current.recipe,liked,critique);
   if(lastOrigin==='loop')loop.feedback(liked);
   else{
     manualIdeas=judgeStructuralIdeas(manualIdeas,liked);
     showHeritage(heritageEvidence(manualIdeas));
   }
   current.judged=true;
   $('ruleKeep').disabled=true;$('ruleReject').disabled=true;
   persistCanvas(current.canvas,current.recipe,true);
   publishSource(current.canvas,'rules',current.recipe);
   if(liked){
     const rows=read(GALLERY)||[];
     rows.push({recipe:current.recipe,thumb:thumbnail(current.canvas)});
     store(GALLERY,rows.slice(-12));gallery();
   }
   status(liked?'KEPT: this law / mark / lineage was recorded.':
     'REJECTED: the criticized law and/or mark system will be less likely in future surprise experiments.');
 }
 function save(){
   if(!current)return;
   const link=document.createElement('a');link.download='hexfield-rule-'+current.recipe.id+'.png';
   link.href=$('ruleArtwork').toDataURL('image/png');document.body.append(link);link.click();link.remove();
 }
 $('rulePaint').addEventListener('click',()=>{loop.pause();void paintFresh();});
 $('ruleReworkBtn').addEventListener('click',()=>{loop.pause();rework();});
 $('ruleNewLaw').addEventListener('click',()=>{loop.pause();child('law');});
 $('ruleNewSubject').addEventListener('click',()=>{loop.pause();child('subject');});
 $('ruleNewMark').addEventListener('click',()=>{loop.pause();child('mark');});
 $('ruleLoopStart').addEventListener('click',()=>loop.start(loopOptions()));
 $('ruleLoopStop').addEventListener('click',()=>{
   loop.pause();
   if(current){persistCanvas(current.canvas,current.recipe,current.judged);
     publishSource(current.canvas,'rules',current.recipe);}
 });
 $('ruleLoopOnce').addEventListener('click',()=>loop.once(loopOptions()));
 for(const id of ['ruleLoopSpeed','ruleMixMode','ruleLockLaw']){
   $(id).addEventListener('change',()=>loop.configure(loopOptions()));
 }
 $('ruleKeep').addEventListener('click',()=>vote(true));
 $('ruleReject').addEventListener('click',()=>vote(false));
 $('ruleSave').addEventListener('click',save);
 $('ruleFile').addEventListener('change',async event=>{
   try{upload=await fileToImage(event.target.files?.[0]);$('ruleReference').value='file';status('Reference image loaded. Your rules will be executed locally.');}
   catch(error){status(safe(error.message));}
 });
 $('ruleReference').addEventListener('change',()=>{
   if($('ruleReference').value==='last'&&!current)status('Paint an image first to use it as your next reference.');
 });
 const restored=read(CURRENT);
 if(restored?.recipe&&restored?.image){
   const image=new Image();image.onload=()=>{
     if(current)return;
     const canvas=fromImage(image);
     context.drawImage(canvas,0,0);
     current={recipe:restored.recipe,canvas,judged:!!restored.judged,metrics:null};
     parentCanvas=canvas;
     $('ruleArtwork').hidden=false;$('ruleEmpty').hidden=true;
     $('ruleKeep').disabled=!!current.judged;$('ruleReject').disabled=!!current.judged;
     $('ruleReworkBtn').disabled=false;$('ruleSave').disabled=false;
     text('ruleCaption',describeRecipe(current.recipe));
     text('ruleEvidence','LAST STUDY RESTORED · CONTINUE FROM THIS CANVAS');
     status('Previous constrained study restored. REWORK paints its own output as a new reference.');
   };image.src=restored.image;
 }
 gallery();
 return {
   show(){if(!current)status('Choose visual laws, or start continuous reabstraction of every available renderer.');},
   hide(){loop.pause();theatre.stop();if(current){persistCanvas(current.canvas,current.recipe,current.judged);
     publishSource(current.canvas,'rules',current.recipe);}},
   paintFresh,hasWork:()=>!!current,
   loopState:()=>loop.state()
 };
}
